def check_2x2_l_shapes(grid, color):
    """Find all L-shapes (3 cells) of given color in 2x2 areas"""
    l_shapes = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            cnt = sum([
                grid[r][c] == color,
                grid[r][c+1] == color,
                grid[r+1][c] == color,
                grid[r+1][c+1] == color
            ])
            if cnt == 3:
                l_shapes.append({
                    'pos': (r, c),
                    'cells': [(r,c), (r,c+1), (r+1,c), (r+1,c+1)],
                })
    return l_shapes

