def apply_3out4_to_9(grid):
    """Apply 3-out-of-4 L-shape transformation: convert those 3 pixels to 9s"""
    result = [row[:] for row in grid]  # Deep copy
    cells_to_change = set()

    # First, find all 3-out-of-4 L-shapes and aggregate cells
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            tl, tr, bl, br = grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]
            colored_cells = []
            if tl != 3: colored_cells.append((r, c))
            if tr != 3: colored_cells.append((r, c+1))
            if bl != 3: colored_cells.append((r+1, c))
            if br != 3: colored_cells.append((r+1, c+1))
            non_bg_cells = [cell for cell in colored_cells if result[cell[0]][cell[1]] != 3]

            # Check for 3 non-background cells of same color
            if len(non_bg_cells) >= 3:
                colors_in_l = [result[cell[0]][cell[1]] for cell in non_bg_cells]
                from collections import Counter
                color_counts = Counter(colors_in_l)
                max_count = max(color_counts.values())

                # If 3 cells have same color (forming L-shape)
                if max_count == 3:
                    for cell in non_bg_cells:
                        cells_to_change.add(cell)

    # Apply transformation
    for cell in cells_to_change:
        r, c = cell
        result[r][c] = 9

    return result

