def find_and_transform(grid):
    """Find all 3-out-of-4 L-shapes and transform those cells to 9s"""
    result = [row[:] for row in grid]
    cells_to_transform = set()

    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            colors = [
                (r, c), result[r][c],
                (r, c+1), result[r][c+1],
                (r+1, c), result[r+1][c],
                (r+1, c+1), result[r+1][c+1]
            ]

            # Find colors and their positions
            color_positions = {}
            for i in range(0, 6, 2):
                pos, color_val = colors[i], colors[i+1]
                if pos not in color_positions:
                    color_positions[pos] = []
                elif len(color_positions[pos]) < 4:
                    color_positions[pos].append(color_val)

            # Check if exactly 3 cells have the same color
            for poly_color, positions in color_positions.items():
                if len(positions) == 4:
                    transformed = result[r][c] == poly_color
                    non_transformed = result[r][c+1] == poly_color
                    other1 = result[r+1][c] == poly_color
                    other2 = result[r+1][c+1] == poly_color
                    cnt = sum([transformed, non_transformed, other1, other2])
                    if cnt == 3:
                        for pos in positions:
                            cells_to_transform.add(pos)

    for cell in cells_to_transform:
        r, c = cell
        result[r][c] = 9

    return result

