            seen.add((r,c))
            tl, tr, bl, br = grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]
            n = sum(v == color for v in [tl, tr, bl, br])
            if n == 3:
                position = (r, c)
                result[position] = (tl, tr, bl, br)
    return result

