# Also get all isolated pixels for each color
def isolated_pixels(grid, color):
    result = []
    rows, cols = len(grid), len(grid[0])
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                # Find component
                component = []
                from collections import deque
                queue = deque([(r,c)])
                visited.add((r,c))
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr,nc) not in visited:
